            if 0 <= x < w and 0 <= y < h and (x, y) not in obstacles:
                res.append((x, y))

    if not res:
        return [0, 0]

    def dist(a, b, c, d):
        dx = abs(a - c)
        dy = abs(b - d)
        return dx if dx >= dy else dy

    def blocked(adj):
        x, y = adj
        if not (0 <= x < w and 0 <= y < h):
            return True
        return (x, y) in obstacles

    def open_score(x, y):
        # count free 8-neighborhood cells (excluding obstacles)
        s = 0
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if not blocked((nx, ny)):
                    s += 1
        return s

